#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <sys/time.h>
#include <time.h>
extern char **environ;
int main(void) {
    struct timespec start, end, pause = {0,30000000};
    struct timeval wall;
    int closed = fcntl(198, F_GETFD) == -1 && errno == EBADF;
    if (clock_gettime(CLOCK_MONOTONIC, &start) || nanosleep(&pause,0) ||
        clock_gettime(CLOCK_MONOTONIC, &end) || gettimeofday(&wall,0)) return 1;
    long long elapsed=(end.tv_sec-start.tv_sec)*1000000000LL+end.tv_nsec-start.tv_nsec;
    printf("%d %d %lld %ld\n",closed,elapsed>=10000000 && elapsed<2000000000,
           (long long)wall.tv_sec,(long)wall.tv_usec);
    for(char **item=environ;*item;item++) {
        for(unsigned char *s=(unsigned char *)*item;*s;s++) printf("%02x",*s);
        putchar('\n');
    }
    return 0;
}

