/* Fixture transport for one external request-clock sample. No PHP evaluation. */
#define _GNU_SOURCE
#include <errno.h>
#include <inttypes.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>
#include <unistd.h>

static struct timeval request_clock;
static int request_clock_ready;

static void invalid_clock(void)
{
    static const char message[] = "php-spec request clock: invalid fixture transport\n";
    (void) write(STDERR_FILENO, message, sizeof(message) - 1);
    _exit(125);
}

__attribute__((constructor)) static void load_request_clock(void)
{
    const char *sample = getenv("PHP_SPEC_REQUEST_CLOCK");
    char *end;
    intmax_t seconds, microseconds;
    if (sample == NULL || (*sample != '-' && (*sample < '0' || *sample > '9')))
        invalid_clock();
    errno = 0;
    seconds = strtoimax(sample, &end, 10);
    if (errno || end == sample || *end != ':')
        invalid_clock();
    sample = end + 1;
    if (*sample < '0' || *sample > '9')
        invalid_clock();
    errno = 0;
    microseconds = strtoimax(sample, &end, 10);
    if (errno || *end != '\0' || microseconds > 999999)
        invalid_clock();
    request_clock.tv_sec = (time_t) seconds;
    request_clock.tv_usec = (suseconds_t) microseconds;
    if ((intmax_t) request_clock.tv_sec != seconds ||
        unsetenv("PHP_SPEC_REQUEST_CLOCK") || unsetenv("LD_PRELOAD"))
        invalid_clock();
    request_clock_ready = 1;
}

int gettimeofday(struct timeval *restrict value, void *restrict timezone)
{
    if (!request_clock_ready || timezone != NULL)
        invalid_clock();
    *value = request_clock;
    return 0;
}
